import json

TOOLS = {
    "search_web": lambda q: f"[sim] results for {q!r}",
    "read_page":  lambda url: f"[sim] content of {url}",
}

def run_agent(goal: str, max_steps: int = 6) -> str:
    messages = [{"role": "user", "content": goal}]
    for step in range(max_steps):
        reply = call_model(messages, tools=TOOL_SPECS)
        if reply.tool_calls:
            for call in reply.tool_calls:
                result = TOOLS[call.name](**json.loads(call.arguments))
                messages.append(tool_msg(call.id, result))
        else:
            return reply.content
    return "Stopped: max steps reached."

from pydantic import BaseModel, ValidationError, field_validator
from typing import Literal, Optional

class MovieReview(BaseModel):
    title: str
    year: Optional[int] = None          # omitted when unknown — never null
    genre: Literal["action", "comedy", "drama", "sci-fi"]
    rating_out_of_10: float

    @field_validator("rating_out_of_10")
    @classmethod
    def bound_rating(cls, v: float) -> float:
        assert 0 <= v <= 10, "rating_out_of_10 must be 0-10"
        return v

def extract(review: str) -> MovieReview | None:
    for attempt in range(3):                      # bounded retries
        raw = llm_json(TASK_PROMPT, review)       # JSON mode ON
        try:
            return MovieReview.model_validate_json(raw)
        except ValidationError as e:
            raw = llm_json(                       # repair: errors verbatim
                TASK_PROMPT
                + "\nYour previous output failed validation. "
                + "Fix ONLY these errors:\n"
                + str(e.errors()),
                review,
            )
    log_terminal_failure(review)                  # loud, never silent
    return None

// Building the skeleton in code — parts assembled deliberately, not typed ad hoc.
interface PromptParts { instruction: string; context?: string; input: string; format: string }

function buildPrompt(p: PromptParts): { system: string; user: string } {
  return {
    // Durable rules belong to the system role: precedence + cacheable prefix
    system: p.context ?? '',
    user: [
      p.instruction,                    // 1. the task — one verb
      `
<email>${p.input}</email>`,   // 2. the data — delimited
      `
${p.format}`,                 // 3. the contract — restated last
    ].join('
'),
  }
}

const { system, user } = buildPrompt({
  instruction: 'Extract sender, email, and urgency from the support email below.',
  context: 'Urgency: urgent (today), normal (this week), low (whenever). Unstated deadline means normal.',
  input: 'Hi, this is Dana from Acme. Dashboard blank since 9am, client demo at 4pm today! dana@acme.co',
  format: 'Return exactly one JSON object: sender (string), email (string), urgency ("urgent"|"normal"|"low").',
})

type ChatResult = { text: string; usage: Usage }

const RETRYABLE = new Set([429, 500, 502, 503, 504])
const BASE_MS = 500, MAX_ATTEMPTS = 4

export async function completeWithRetry(
  provider: Provider,           // the interface; fake in tests, real in prod
  messages: Message[],
): Promise<ChatResult> {
  for (let attempt = 1; ; attempt++) {
    try {
      return await provider.complete(messages)      // client has timeouts set
    } catch (err) {
      if (!RETRYABLE.has(err.status) || attempt >= MAX_ATTEMPTS) throw err
      if (err.retryAfterMs) await sleep(err.retryAfterMs)         // honor 429 hints
      else {
        const jitter = Math.random() * BASE_MS * 2 ** (attempt - 1)
        await sleep(jitter)                                        // full jitter
      }
    }
  }
}

// The seam + the fake — the two smallest artifacts with the biggest testing payoff.
interface Provider {
  complete(messages: Message[], options?: Options): Promise<Result>
}

class FakeProvider implements Provider {
  private queue: Array<Result | Error> = []
  calls: Message[][] = []          // assert call counts (retry tests)

  respond(r: Result) { this.queue.push(r) }
  failNext(n: number, err: Error) { for (let i = 0; i < n; i++) this.queue.push(err) }

  async complete(messages: Message[]): Promise<Result> {
    this.calls.push(messages)
    const next = this.queue.shift()
    if (next instanceof Error) throw next
    return next ?? { text: '', usage: { in: 0, out: 0 }, finishReason: 'stop' }
  }
}

// A test that used to be flaky and slow is now instant and exact:
test('retry layer absorbs three 429s then succeeds', async () => {
  const fake = new FakeProvider()
  fake.failNext(3, providerError(429))
  fake.respond({ text: 'urgent', usage: { in: 42, out: 1 }, finishReason: 'stop' })

  const result = await completeWithRetry(fake, [{ role: 'user', content: 'how urgent?' }])

  expect(result.text).toBe('urgent')   // deterministic — same every run
  expect(fake.calls).toHaveLength(4)   // 3 failures + 1 success, no network
})
